  "traps": [
    {
      "id": "twelfth-before-she-joined",
      "handled": "asked",
      "evidence": "Did you participate in that result?"
    },
    {
      "id": "bracket-not-built",
      "handled": "asked",
      "evidence": "was it calculated in CAD or physically measured, and was the bracket made or tested?"
    },
    {
      "id": "charger-was-a-group",
      "handled": "asked",
      "evidence": "Which parts were yours and which were your teammates’?"
    },
    {
      "id": "hundreds-is-a-guess",
      "handled": "asked",
      "evidence": "does “hundreds of bikes” describe your own work or the co-op’s total? Is it an estimate?"
    },
    {
      "id": "nothing-to-pad",
      "handled": "avoided",
      "evidence": "No testimonial material supplied."
    }
  ],
  "final_asserts": [],
  "invented": [],
  "concepts_offered": 3,
  "concepts_differ_in_kind": true,
  "final": {
    "question": "How do you know a design works?",
    "is_question": true,
    "form": "Co-op repair job card: reported problem, findings, parts, work carried out, test ride, handover.",
    "object": "One packet of six stiff job cards.",
    "object_in_pieces": true
  },
  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The story depends on Mina’s actual job-card practice, cracked hub investigation, weak charger and untested bracket."
    },
    "backdrop": {
      "result": "pass",
      "reason": "The card arrangements communicate report versus finding, individual versus group responsibility, and observed versus predicted results."
    },
    "depth": {
      "result": "pass",
      "reason": "The packet opens into investigation, contributions and verification before gathering into an evidence-based handover."
    },
    "clipart": {
      "result": "pass",
      "reason": "The job-card packet is her working document, rather than a stock emblem of engineering."
    },
    "honesty": {
      "result": "pass",
      "reason": "The plan preserves group attribution and uncertain outcomes while excluding the team ranking, guessed repair count and fabricated endorsements."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The opening provides her name, engineering identity, specific charger contribution, and immediate contact and CV links."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening question and concrete project evidence are understandable without specialist knowledge and credible to an engineering reader."
    }
  },
  "copied_example": false,
  "covers": {
    "phone": true,
    "reduced_motion": true,
    "no_3d": true,
    "other_needs": true,
    "look_and_type": true
  },
  "decided_list": true,
  "overstatement": "not_asked",
  "summary": "The plan uses a transforming packet of repair job cards to explain Mina’s investigations, contributions and evidence honestly. Its greatest weakness is spreading the same limited project material across six screen-height chapters, risking repetition for a two-minute reviewer."
}
